package roster_test

import (
	"encoding/json"
	"os"
	"sort"
	"testing"

	"github.com/charles161/botlink/server/internal/roster"
)

// crypto/vectors/roster.json (generated by the client workstream): the valid log verifies to the
// expected state; every invalid variant fails with the expected rule at the expected seq.
func TestRosterVectors(t *testing.T) {
	b, err := os.ReadFile("../../../crypto/vectors/roster.json")
	if err != nil {
		t.Skip("crypto/vectors/roster.json not present yet")
	}
	var v struct {
		RoomID string `json:"room_id"`
		Valid  struct {
			Entries []roster.Wire `json:"entries"`
			Expect  struct {
				RoomName string `json:"room_name"`
				RoomFP   string `json:"room_fp"`
				Owner    string `json:"owner"`
				HeadSeq  int    `json:"head_seq"`
				HeadHash string `json:"head_hash"`
				People   []struct {
					Account string   `json:"account"`
					Devices []string `json:"devices"`
				} `json:"people"`
				Members []struct {
					ID      string `json:"id"`
					Account string `json:"account"`
					Name    string `json:"name"`
					Ed      string `json:"ed"`
					X       string `json:"x"`
				} `json:"members"`
			} `json:"expect"`
		} `json:"valid"`
		Invalid []struct {
			Name    string        `json:"name"`
			Entries []roster.Wire `json:"entries"`
			Expect  struct {
				Rule string `json:"rule"`
				Seq  int    `json:"seq"`
			} `json:"expect"`
		} `json:"invalid"`
	}
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	st, err := roster.Replay(v.RoomID, v.Valid.Entries)
	if err != nil {
		t.Fatalf("valid log rejected: %v", err)
	}
	ex := v.Valid.Expect
	if st.Name != ex.RoomName || st.RoomFP() != ex.RoomFP || st.Owner != ex.Owner || st.HeadSeq != ex.HeadSeq {
		t.Fatalf("state: name %s fp %s owner %s head %d", st.Name, st.RoomFP(), st.Owner, st.HeadSeq)
	}
	if got := hexOf(st.HeadHash); got != ex.HeadHash {
		t.Fatalf("head hash %s", got)
	}
	for _, p := range ex.People {
		for _, d := range p.Devices {
			if !st.IsDeviceOf(d, p.Account) {
				t.Fatalf("device %s of %s missing", d, p.Account)
			}
		}
	}
	active := st.ActiveMembers()
	if len(active) != len(ex.Members) {
		t.Fatalf("active members %d, want %d", len(active), len(ex.Members))
	}
	sort.Slice(active, func(i, j int) bool { return active[i].ID < active[j].ID })
	for _, m := range ex.Members {
		got := st.Members[m.ID]
		if got == nil || !got.Active || got.Account != m.Account || got.Name != m.Name || got.Ed != m.Ed || got.X != m.X {
			t.Fatalf("member %s: %+v", m.ID, got)
		}
	}
	for _, inv := range v.Invalid {
		_, err := roster.Replay(v.RoomID, inv.Entries)
		re, ok := err.(*roster.Error)
		if !ok || re.Rule != inv.Expect.Rule || re.Seq != inv.Expect.Seq {
			t.Errorf("%s: want %s@%d, got %v", inv.Name, inv.Expect.Rule, inv.Expect.Seq, err)
		}
	}
	t.Logf("roster vectors: valid log ok, %d invalid variants rejected with the expected rule", len(v.Invalid))
}

func hexOf(b []byte) string {
	const h = "0123456789abcdef"
	out := make([]byte, len(b)*2)
	for i, c := range b {
		out[i*2], out[i*2+1] = h[c>>4], h[c&15]
	}
	return string(out)
}
